SELECT COALESCE(
           ROUND(
               SUM(CASE WHEN p.status = 'ENDED' THEN 1 ELSE 0 END) * 100.0
               / NULLIF(COUNT(*), 0)
           ),
           0
       )
FROM performance p
WHERE p.employee_id = #{employeeId}
  AND p.work_item = 'PERSONAL'
  AND YEAR(COALESCE(p.start_date, p.created_at)) = #{targetYear}

SELECT COALESCE(
           ROUND(
               SUM(CASE WHEN p.status = 'ENDED' THEN 1 ELSE 0 END) * 100.0
               / NULLIF(COUNT(*), 0)
           ),
           0
       )
FROM performance p
WHERE p.employee_id = #{employeeId}
  AND p.work_item = 'TEAM'
  AND YEAR(COALESCE(p.start_date, p.created_at)) = #{targetYear}

SELECT COALESCE(
           ROUND(
               SUM(CASE WHEN p.status = 'ENDED' THEN 1 ELSE 0 END) * 100.0
               / NULLIF(COUNT(*), 0)
           ),
           0
       )
FROM performance p
WHERE p.employee_id = #{employeeId}
  AND p.expected_end_date IS NOT NULL
  AND YEAR(p.expected_end_date) = #{targetYear}
